   WHERE n.nspname||'.'||p.proname=ANY(ARRAY['listing_publication_private.managed_image_gallery_projection_v1','listing_publication_private.protect_managed_image_addition_v1','listing_publication_private.managed_image_family_v1','listing_publication_private.managed_image_origins_v1','listing_publication_private.managed_image_root_v1','listing_publication_private.managed_image_addition_receipt_v1','listing_publication_private.allocate_managed_publication_attempt_v1','listing_publication_private.normalize_managed_image_addition_v1','listing_publication_private.require_managed_image_policies_v1','listing_publication_private.managed_image_addition_journey_v1','listing_publication_private.lock_managed_image_addition_parent_v1','listing_publication_private.managed_image_addition_status_v1','public.get_my_managed_listing_image_addition_v1','public.prepare_my_managed_listing_image_addition_v1','public.cancel_my_managed_listing_image_addition_v1','public.append_my_managed_listing_image_v1','listing_publication_private.assert_ordinary_publication_v1','listing_publication_private.managed_image_cleanup_task_v2','listing_publication_private.lock_managed_listing_images_v1','public.set_my_managed_listing_primary_image_v1','public.remove_my_managed_listing_image_v1','public.prepare_my_listing_publication_v1','listing_publication_private.protect_attempt','listing_publication_private.apply_final','listing_publication_private.final_material','public.get_my_listing_publication_confirmation_v1','public.publish_my_listing_v1','listing_publication_private.apply_delete','listing_publication_private.final_receipt','public.get_public_listing_media_binding_v1','public.get_my_listing_media_binding_v2','public.get_my_managed_listing_v2','listing_publication_private.lock_multipart_cleanup_context','public.claim_listing_published_source_cleanup_v1','public.record_listing_published_source_cleanup_v1','listing_publication_private.hosted_retired_web_deleted_v1','public.claim_listing_retired_web_cleanup_v1','public.record_listing_retired_web_cleanup_v1','public.get_my_listing_retired_web_cleanup_v1','public.prepare_listing_multipart_cleanup_v2','public.claim_listing_cleanup_for_attempt_v2']::text[]))=41 AS capability_present
 FROM measured),
 assessed AS (SELECT *,coalesce(functions AND installer AND actor_roles AND closed_private_schema AND core_relations
  AND required_columns AND managed_triggers AND final_writer_policies AND hosted_context_ready,false) dependencies_ok FROM checks),
 result_row AS (SELECT jsonb_build_object('schema_version',1,'kind','listing-published-photo-addition-v1',
  'state',CASE WHEN dependencies_ok AND capability_absent AND NOT capability_present THEN 'absent'
   WHEN dependencies_ok AND capability_present AND NOT capability_absent THEN 'applied' ELSE 'unknown' END,
  'recognized',dependencies_ok AND (capability_absent<>capability_present),
  'ready_to_apply',dependencies_ok AND capability_absent AND NOT capability_present,'dependencies_ok',dependencies_ok,
  'capability_absent',capability_absent,'capability_present',capability_present,
  'guards',to_jsonb(assessed)-ARRAY['dependencies_ok','capability_absent','capability_present'],
  'hosted_context',(SELECT context FROM hosted),
  'fingerprints',jsonb_build_object('dependencies',dependencies,'capability',capability),
  'invariants',jsonb_build_object('existing_functions',existing_functions,'existing_authority',existing_authority,'immutable_structure',immutable_structure)) result
 FROM assessed CROSS JOIN measured)
 SELECT result FROM result_row;
DO $after$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM photo_addition_install_after a CROSS JOIN photo_addition_install_before b
  WHERE a.result->>'state'='applied' AND a.result->'invariants'=b.result->'invariants'
   AND a.result->'fingerprints'->>'dependencies'=b.result->'fingerprints'->>'dependencies') THEN
  RAISE EXCEPTION 'LISTING_PUBLISHED_PHOTO_ADDITION_INSTALLED_STATE_NOT_VERIFIED' USING ERRCODE='55000';
 END IF;
END $after$;
NOTIFY pgrst,'reload schema';
SELECT result FROM photo_addition_install_after;
COMMIT;
